%[text] %[text:anchor:T_1FFD3858] # Longitudinal Vehicle - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Coast-down
model_name = "HarnessModel_Vehicle1D";
load_system(model_name)

Vehicle1D_Basic_params

set_param(model_name + "/Longitudinal Vehicle", ReferencedSubsystem = "Vehicle1D_Basic_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_Vehicle1D_Coastdown_refsub");
%[text] 
initial.vehicle_speed_kph = 100;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "200");

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

signal_names = [
  "Axle torque input"
  "Brake force"
  "Road inclination"
  "Road grade"
  "G force"
  "Vehicle speed kph"
  "Vehicle speed mph"
  "Axle speed"
  ];

for idx = 1 : numel(signal_names) %[output:group:4bb30e90]
  fig = SignalUtil1.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:6a97607f] %[output:9c14cd34] %[output:65f30b87] %[output:36866b70] %[output:31f7e00d] %[output:377566d9] %[output:2d75a89a] %[output:9bdd9ad1]
  fig.Position(4) = 150;  % height
end  % for %[output:group:4bb30e90]
